const $=id=>document.getElementById(id),params=new URLSearchParams(location.search);
const names={qp:'题卷',ms:'评分标准',er:'考官报告',gt:'分数线',ci:'实验说明',pm:'预发布材料'},seasons={m:'2–3月',s:'5–6月',w:'10–11月'};
const storageKey='pp-igcse-ui-v2',defaults=()=>({year:'2024',session:'all',kind:'papers',group:'all',scope:'all',variant:'all',search:''});
let saved={};try{const value=JSON.parse(localStorage.getItem(storageKey)||'{}');if(value&&typeof value==='object'&&!Array.isArray(value))saved=value}catch{}
let subject=params.get('subject')==='cs'?'cs':'physics',files=[],pairs=[],index=new Map(),selected=null,rows=[],filters=defaults(),preferredType='qp',compare=saved.compare===true,collapsed=false;
const mobile=()=>matchMedia('(max-width:760px)').matches,canCompare=()=>matchMedia('(min-width:1101px)').matches;
for(let year=2024;year>=2019;year--)$('year').add(new Option(String(year),String(year)));
function sameExam(a,b){return a&&b&&a.subject===b.subject&&a.year===b.year&&a.session===b.session&&a.paper===b.paper&&['qp','ms'].includes(a.type)&&['qp','ms'].includes(b.type)}
function pair(file,type){return file&&['qp','ms'].includes(file.type)?index.get(file.filename.replace(/_(qp|ms)_/,'_'+type+'_')):null}
function description(file){const p=Number(file.paper?.[0]);return file.subject==='physics'?({1:'选择题 · Core',2:'选择题 · Extended',3:'理论题 · Core',4:'理论题 · Extended',5:'实验操作',6:'替代实验'}[p]||names[file.type]):({1:file.year>=2023?'计算机系统':'理论知识',2:'算法与编程'}[p]||names[file.type])}
function groups(){return subject==='physics'?[['all','全部'],['mcq','选择题'],['theory','理论题'],['practical','实验题']]:[['all','全部'],['1','Paper 1'],['2','Paper 2']]}
function validFilters(value){const next=defaults();if(!value||typeof value!=='object')return next;
 for(const [key,allowed] of Object.entries({year:['all','2019','2020','2021','2022','2023','2024'],session:['all','m','s','w'],kind:['papers','all','er','gt','ci','pm'],scope:['all','core','extended'],variant:['all','1','2','3'],group:groups().map(g=>g[0])}))if(allowed.includes(value[key]))next[key]=value[key];
 if(typeof value.search==='string')next.search=value.search.slice(0,150);if(!['papers','all'].includes(next.kind)){next.group='all';next.scope='all';next.variant='all'}return next}
function remember(){try{saved[subject]={...filters,lastFile:selected?.filename||null,preferredType};saved.compare=compare;localStorage.setItem(storageKey,JSON.stringify(saved))}catch{}}
function filtersToUI(){for(const id of ['year','kind','scope','variant'])$(id).value=filters[id];$('search').value=filters.search;$('scope-label').hidden=subject==='cs';const sessionOnly=['er','gt'].includes(filters.kind);document.querySelector('.paper-filter').hidden=sessionOnly;$('advanced').hidden=sessionOnly;
 $('clear-search').hidden=!filters.search;$('advanced-label').textContent='更多筛选'+((filters.scope!=='all'&&subject==='physics'?1:0)+(filters.variant!=='all'?1:0)?' · 已筛选':'');
 for(const button of document.querySelectorAll('[data-session]')){const on=button.dataset.session===filters.session;button.classList.toggle('active',on);button.setAttribute('aria-pressed',String(on))}
 if($('paper-groups').dataset.subject!==subject){$('paper-groups').dataset.subject=subject;$('paper-groups').replaceChildren();for(const [key,label] of groups()){const button=document.createElement('button');button.textContent=label;button.dataset.group=key;button.classList.toggle('active',filters.group===key);button.setAttribute('aria-pressed',String(filters.group===key));button.onclick=()=>{filters.group=key;list()};$('paper-groups').append(button)}}for(const button of $('paper-groups').children){const on=button.dataset.group===filters.group;button.classList.toggle('active',on);button.setAttribute('aria-pressed',String(on))}
}
function readerURL(file){const url=new URL('igcse-reader.html',location.href);url.search=new URLSearchParams({subject:file.subject,file:file.filename});return url.href}
function loadFrame(id,file){const frame=$(id);if(frame.dataset.file!==file.filename){frame.dataset.file=file.filename;frame.src=readerURL(file)}}
function clearFrame(id){const frame=$(id);if(frame.hasAttribute('src'))frame.removeAttribute('src');delete frame.dataset.file}
function selectedStyle(){for(const card of document.querySelectorAll('.paper')){const file=index.get(card.dataset.file),on=!!selected&&(file.filename===selected.filename||sameExam(file,selected));card.classList.toggle('selected',on);for(const button of card.querySelectorAll('[data-type]')){const active=on&&button.dataset.type===selected.type;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))}}}
function updateDirectory(){if(mobile()){$('workspace').classList.remove('catalogue-collapsed');$('list-toggle').setAttribute('aria-expanded',String(!$('workspace').classList.contains('reading')));$('list-toggle').title='返回试卷目录'}else{$('workspace').classList.toggle('catalogue-collapsed',collapsed);$('list-toggle').setAttribute('aria-expanded',String(!collapsed));$('list-toggle').title=collapsed?'展开试卷目录':'收起试卷目录'}}
function renderReader(){
 if(!selected)return;const qp=pair(selected,'qp'),ms=pair(selected,'ms'),both=!!qp&&!!ms,split=compare&&both&&canCompare();
 $('viewer-layout').hidden=false;$('reader-empty').hidden=true;$('viewer-layout').classList.toggle('comparison',split);$('answer-pane').hidden=!split;$('question-label').hidden=!split;
 $('document-tabs').hidden=split||!['qp','ms'].includes(selected.type);
 for(const [type,id] of [['qp','show-qp'],['ms','show-ms']]){const target=pair(selected,type);$(id).disabled=!target;$(id).setAttribute('aria-pressed',String(selected.type===type));$(id).onclick=()=>select(target,{activate:true})}
 $('compare').disabled=!both;$('compare').classList.toggle('active',split);$('compare').setAttribute('aria-pressed',String(split));
 $('title').textContent=selected.year+' · '+seasons[selected.session]+(selected.paper?' · Paper '+selected.paper[0]+' / V'+selected.paper.slice(1):'');
 $('reader-meta').textContent=description(selected)+(split?' · 题卷与答案对照':' · '+names[selected.type]);
 $('direct').href=readerURL(selected);$('direct').removeAttribute('aria-disabled');
 const position=rows.findIndex(f=>f.filename===selected.filename||sameExam(f,selected));$('previous-exam').disabled=position<=0;$('next-exam').disabled=position<0||position>=rows.length-1;
 $('resume').hidden=false;
 if(!mobile()||$('workspace').classList.contains('reading')){if(split){loadFrame('reader-frame',qp);loadFrame('answer-frame',ms)}else{loadFrame('reader-frame',selected);clearFrame('answer-frame')}}
 const query=new URLSearchParams({subject,file:selected.filename});history.replaceState(null,'','?'+query);selectedStyle();updateDirectory();
}
function revealSelected(){const card=document.querySelector('.paper.selected');if(card&&$('catalogue').getClientRects().length&&!collapsed)card.scrollIntoView({block:'nearest'})}
function select(file,{activate=false}={}){if(!file||file.subject!==subject)return;selected=file;if(['qp','ms'].includes(file.type))preferredType=file.type;if(activate&&mobile())$('workspace').classList.add('reading');renderReader();remember();if(activate)requestAnimationFrame(revealSelected)}
function clearReader(){selected=null;history.replaceState(null,'','?'+new URLSearchParams({subject}));clearFrame('reader-frame');clearFrame('answer-frame');$('viewer-layout').hidden=true;$('reader-empty').hidden=false;$('reader-empty').querySelector('h2').textContent='没有匹配的资料';$('reader-empty').querySelector('p').textContent='试试减少筛选条件，或清空搜索。';$('title').textContent='选择试卷';$('reader-meta').textContent='题卷与评分标准';$('direct').removeAttribute('href');$('direct').setAttribute('aria-disabled','true');$('resume').hidden=true;for(const id of ['show-qp','show-ms','compare','previous-exam','next-exam'])$(id).disabled=true}
function matches(file){const paper=Number(file.paper?.[0]);
 if(file.subject!==subject||(filters.year!=='all'&&String(file.year)!==filters.year)||(filters.session!=='all'&&file.session!==filters.session))return false;
 if(filters.kind!=='all'&&(filters.kind==='papers'?!['qp','ms'].includes(file.type):file.type!==filters.kind))return false;
 if(filters.variant!=='all'&&file.paper?.slice(1)!==filters.variant)return false;
 if(filters.group!=='all'){if(subject==='cs'){if(String(paper)!==filters.group)return false}else if(!(filters.group==='mcq'?[1,2]:filters.group==='theory'?[3,4]:[5,6]).includes(paper))return false}
 if(subject==='physics'&&filters.scope!=='all'&&!(filters.scope==='core'?[1,3,5,6]:[2,4,5,6]).includes(paper))return false;
 const haystack=(file.filename+' '+file.year+' '+file.paper+' p'+paper+' paper '+paper+' '+description(file)+' '+names[file.type]+' '+seasons[file.session]).toLowerCase();return filters.search.trim().toLowerCase().split(/\s+/).filter(Boolean).every(token=>haystack.includes(token))
}
function list(){
 document.querySelectorAll('[data-subject]').forEach(button=>{const active=button.dataset.subject===subject;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});$('subject-title').textContent=subject==='physics'?'物理试卷':'计算机科学';$('practice').href='igcse-practice.html?subject='+subject;document.title=(subject==='physics'?'Physics 0625':'Computer Science 0478')+' · Pure Practice';filtersToUI();rows=pairs.filter(matches);$('papers').replaceChildren();$('papers').scrollTop=0;$('count').textContent=rows.length+(filters.kind==='papers'?' 份试卷':' 项资料');
 if(!rows.length){const empty=document.createElement('div');empty.className='empty-results';const message=document.createElement('p');message.textContent='没有找到匹配的资料';const button=document.createElement('button');button.textContent='重置筛选';button.onclick=reset;empty.append(message,button);if(filters.year!=='all'&&!['papers','all'].includes(filters.kind)&&pairs.some(f=>f.subject===subject&&f.type===filters.kind)){message.textContent=filters.year+' 年暂无符合筛选的'+names[filters.kind];const allYears=document.createElement('button');allYears.textContent='查看全部年份';allYears.onclick=()=>{filters.year='all';list()};empty.insertBefore(allYears,button)}$('papers').append(empty);clearReader();remember();return}
 let section=null,key='';for(const file of rows){const nextKey=file.year+'-'+file.session;if(nextKey!==key){key=nextKey;section=document.createElement('section');section.className='series-group';const heading=document.createElement('h2');heading.className='series-heading';heading.textContent=file.year+' · '+seasons[file.session]+(file.year===2020&&file.session==='s'?' · 当季材料':'');const count=document.createElement('span');count.textContent=rows.filter(f=>f.year===file.year&&f.session===file.session).length+'份';heading.append(count);section.append(heading);$('papers').append(section)}
 const card=document.createElement('article');card.className='paper';card.dataset.file=file.filename;const primary=document.createElement('button');primary.className='paper-open';primary.title='阅读 '+file.filename;primary.setAttribute('aria-label',(file.paper?'Paper '+file.paper:description(file))+'，'+file.year+' '+seasons[file.session]);const number=document.createElement('span');number.className='paper-number';number.textContent=file.paper?'P'+file.paper[0]:'PDF';const info=document.createElement('span');info.className='paper-info';const title=document.createElement('b');title.textContent=file.paper?'Paper '+file.paper[0]:names[file.type];if(file.paper){const variant=document.createElement('small');variant.textContent='V'+file.paper.slice(1);title.append(variant)}const desc=document.createElement('small');desc.textContent=description(file);info.append(title,desc);primary.append(number,info);primary.onclick=()=>select(pair(file,preferredType)||file,{activate:true});const actions=document.createElement('div');actions.className='paper-actions';for(const type of ['qp','ms']){const target=pair(file,type);if(target){const button=document.createElement('button');button.textContent=type==='qp'?'题卷':'答案';button.dataset.type=type;button.setAttribute('aria-label',(type==='qp'?'题卷':'答案')+' '+file.filename);button.onclick=()=>select(target,{activate:true});actions.append(button)}}card.append(primary,actions);section.append(card)
 }
 if(!selected||!rows.some(file=>file.filename===selected.filename||sameExam(file,selected))){const initial=rows.find(f=>f.type==='qp'&&f.paper===(subject==='physics'?'42':'12'))||rows[0];select(pair(initial,preferredType)||initial)}else{renderReader();remember()}
}
function reset(){filters=defaults();list()}
function restore(next,explicit=null){subject=next;filters=validFilters(saved[subject]);preferredType=saved[subject]?.preferredType==='ms'?'ms':'qp';selected=index.get(saved[subject]?.lastFile)||null;if(selected?.subject!==subject)selected=null;if(explicit?.subject===subject){if(saved[subject]?.lastFile!==explicit.filename)filters={...defaults(),year:String(explicit.year),kind:['qp','ms'].includes(explicit.type)?'papers':explicit.type};selected=explicit;preferredType=explicit.type==='ms'?'ms':'qp'}$('workspace').classList.remove('reading');list();requestAnimationFrame(revealSelected)}
for(const button of document.querySelectorAll('[data-subject]'))button.onclick=()=>{remember();restore(button.dataset.subject)};
for(const id of ['year','kind','scope','variant'])$(id).onchange=()=>{filters[id]=$(id).value;if(id==='kind'&&!['papers','all'].includes(filters.kind)){filters.group='all';filters.scope='all';filters.variant='all'}list()};
for(const button of document.querySelectorAll('[data-session]'))button.onclick=()=>{filters.session=button.dataset.session;list()};
$('search').oninput=()=>{filters.search=$('search').value;list()};$('clear-search').onclick=()=>{filters.search='';list();$('search').focus()};$('reset').onclick=reset;
$('list-toggle').onclick=()=>{if(mobile())$('workspace').classList.toggle('reading');else collapsed=!collapsed;updateDirectory();if(!mobile()||$('workspace').classList.contains('reading'))renderReader();else requestAnimationFrame(revealSelected)};
$('resume').onclick=()=>{if(selected){$('workspace').classList.add('reading');renderReader()}};
for(const [id,direction] of [['previous-exam',-1],['next-exam',1]])$(id).onclick=()=>{const position=rows.findIndex(f=>f.filename===selected?.filename||sameExam(f,selected)),next=rows[position+direction];if(next)select(pair(next,preferredType)||next,{activate:true})};
$('compare').onclick=()=>{compare=!compare;renderReader();remember()};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('reader').requestFullscreen()}catch{$('direct').click()}};
window.addEventListener('message',event=>{if(event.origin!==location.origin||![document.getElementById('reader-frame').contentWindow,document.getElementById('answer-frame').contentWindow].includes(event.source)||event.data?.type!=='igcse-selected')return;const sender=['reader-frame','answer-frame'].map(id=>$(id)).find(frame=>frame.contentWindow===event.source);if(!sender||sender.dataset.file!==event.data.filename)return;const file=index.get(event.data.filename);if(!file||file.subject!==subject||(compare&&canCompare()&&sameExam(file,selected)))return;if(file.filename!==selected?.filename){selected=file;preferredType=file.type==='ms'?'ms':'qp';renderReader();remember()}});
let lastLayout=mobile()+'-'+canCompare();window.addEventListener('resize',()=>{const layout=mobile()+'-'+canCompare();if(layout!==lastLayout){lastLayout=layout;updateDirectory();renderReader()}});
async function start(){try{const response=await fetch('data/igcse-online-files.json');if(!response.ok)throw Error('HTTP '+response.status);files=(await response.json()).files;index=new Map(files.map(file=>[file.filename,file]));pairs=files.filter(file=>file.type!=='ms'||!index.has(file.filename.replace('_ms_','_qp_'))).sort((a,b)=>b.year-a.year||({w:3,s:2,m:1}[b.session]-{w:3,s:2,m:1}[a.session])||Number(a.paper||0)-Number(b.paper||0)||a.filename.localeCompare(b.filename));restore(subject,index.get(params.get('file')))}catch(error){$('count').textContent='目录暂未载入';$('reader-empty').querySelector('h2').textContent='连接暂时中断';$('reader-empty').querySelector('p').textContent='请重新载入试卷目录。';$('retry').hidden=false;$('retry').onclick=()=>location.reload();console.error(error)}}
start();
